package com.kakaplywoods.crm;
import jakarta.persistence.*;import java.time.OffsetDateTime;import java.util.UUID;
@Entity @Table(name="lead_activities") public class LeadActivity {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(name="lead_id",nullable=false) private UUID leadId;@Column(name="activity_type",nullable=false) private String type;@Column(nullable=false,length=2000) private String content;@Column(name="created_by",nullable=false) private String createdBy="admin";@Column(name="created_at",nullable=false) private OffsetDateTime createdAt=OffsetDateTime.now();protected LeadActivity(){}public LeadActivity(UUID leadId,String type,String content){this.leadId=leadId;this.type=type;this.content=content;}public UUID getId(){return id;}public UUID getLeadId(){return leadId;}public String getType(){return type;}public String getContent(){return content;}public String getCreatedBy(){return createdBy;}public OffsetDateTime getCreatedAt(){return createdAt;}}
